struct Base {
  Base() { f(); }
  virtual void f() = 0;
  virtual ~Base() { f(); }
};

struct D : Base {
  void f() override {}
};

bool done = false;

void worker() {
  while (!done) {}
}

void stop() {
  done = true;
}

std::atomic<bool> ready{false};
int value;

void publish() {
  value = 42;
  ready.store(true, std::memory_order_release);
}
void consume() {
  if (ready.load(std::memory_order_acquire)) use(value);
}

